using System;
using System.Collections.Generic;
using System.Linq;
using RichAudio.NativeSuppression01;
internal static class TestAutomaticSetup11 {
    static int cases,assertions;static Fixture current;static readonly List<Fixture> fixtures=new List<Fixture>();
    static void Check(bool b,string why){assertions++;if(!b)throw new Exception(why);}
    internal sealed class Journal:IRunJournal {
        internal readonly List<string> Lines=new List<string>();long seq;
        public bool Healthy{get{return true;}}public long Write(string s){Lines.Add(s);return ++seq;}public bool Durable(long s){return s<=seq;}
    }
    sealed class Fixture {
        internal readonly SetupGame11 Game=new SetupGame11();internal readonly Journal Log=new Journal();
        internal readonly IdleNativeApi Api;internal readonly AutomaticRun Run;internal CaptureLease Capture;int token=10;
        internal Fixture(){current=this;fixtures.Add(this);Api=new IdleNativeApi(null,s=>Log.Write(s),Game,()=>Game.Now,1000);Run=new AutomaticRun(Api,Log,()=>Game.Now,1000,()=>++token,"authored11");Step();Step();}
        internal void Step(double seconds=.05){Game.Advance(seconds);Capture=new CaptureLease{Session="authored11",Recording="authored-media",RecordingActive=true,Foreground=true,TimelineReady=true,StartupAdmitted=true,ObservedTicks=Game.Now};Run.Tick(Capture);}
        internal RunCommand Command(string op="Review",string decision=null){var s=Run.State;return new RunCommand{Session=s.Session,Id=Guid.NewGuid().ToString("N"),Phase=s.Phase,Generation=s.Generation,Observation=s.Observation,Profile=s.Profile,Operation=op,Decision=decision??(s.Phase.StartsWith("B-")?"ControlNormal":s.Phase=="1"?"DistinctEngine":s.Phase=="3"?"MatchedEngine":"Normal"),Text="AUTHORED offline response; not human perception or approval",ExpiresTicks=Game.Now+5000,CaptureReviewed=true,ContextReviewed=true,EvidenceSha256=new string('a',64)};}
        internal void Begin(){Check(Run.Command(Command("Begin"),Capture)=="accepted start","begin actual runner");}
        internal void Review(string decision=null){Check(Run.Command(Command("Review",decision),Capture).StartsWith("accepted"),"review actual binding");}
        internal void Until(Func<bool> condition,double limit=620){long end=Game.Now+(long)(limit*1000);while(!condition()&&!Run.State.Finished&&Game.Now<end)Step();Check(condition(),"expected state; actual="+Run.State.Stage+" "+Run.State.Status+"\n"+string.Join("\n",Log.Lines.Skip(Math.Max(0,Log.Lines.Count-5))));}
        internal void Stage(string s){Until(()=>Run.State.Stage==s);}
        internal void At(string phase){Until(()=>Run.State.AwaitingReview&&Run.State.Phase==phase);}
        internal void Finish(bool review=false){long end=Game.Now+620000;while(!Run.State.Finished&&Game.Now<end){if(review&&Run.State.AwaitingReview)Review();Step();}Check(Run.State.Finished,"bounded termination");}
        internal void Stop(){Run.Stop("AUTHORED stop",Capture);Finish();}
        internal bool Has(string text){return Log.Lines.Any(s=>s.Contains(text));}
        internal void SafeRetired(){Check(Run.State.Retired&&Game.N("delete-100")==1&&Game.N("delete-101")==1,"both exact owned identities disappeared after one delete each");Check(Game.Entities.Values.All(e=>!e.Exists),"native return alone not accepted as deletion");}
    }
    static void Test(string name,Action action){int first=fixtures.Count;action();cases++;for(int i=first;i<fixtures.Count;i++)System.IO.File.WriteAllLines(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(typeof(TestAutomaticSetup11).Assembly.Location),"case-"+cases.ToString("D2")+"-fixture-"+i.ToString("D3")+".log"),fixtures[i].Log.Lines);Console.WriteLine("PASS "+name);}
    public static int Main(){try{
        // Only the disposable test directory contains the explicit string-pin
        // stand-in. Production builds never include this test source or DLL.
        Test("complete delayed native adapter/controller path preserves all five assignments",()=>{var f=new Fixture();f.Game.CollisionAt=f.Game.Now+600;f.Game.GroundAt=f.Game.Now+1200;f.Begin();f.Finish(true);Check(f.Game.Profiles.SequenceEqual(IdleExperiment.Profiles),"exact approved A-only phase order");f.SafeRetired();Check(f.Game.GroundWrites>0&&f.Game.DeleteWrites==2&&f.Game.N("seat")==2&&f.Game.N("start-101")==1,"real SDK pointer/start/seat paths");Check(f.Has("PENDING")&&f.Has("waiting-for-exact-pair-motion-and-contact"),"delayed physical states observed");});
        Test("automatic A engine-on satisfies both setup starts without setter",()=>{var f=new Fixture();f.Game.AutoEngine=true;f.Begin();f.Finish(true);Check(f.Game.Profiles.Count==5&&f.Game.N("start-100")==0&&f.Game.N("start-101")==1,"already-running A does not consume starts");f.SafeRetired();});
        Test("engine command waits across callbacks without resend",()=>{var f=new Fixture();f.Game.EngineDelay=2;f.Begin();f.Stage("InitialView");Check(f.Game.N("start-100")==1&&f.Game.N("start-101")==1,"one request each during delayed start");f.Stop();f.SafeRetired();});
        Test("post-seating motion waits before A engine setter",()=>{var f=new Fixture();f.Game.SeatPhysicsDelay=1.5;f.Begin();f.Stage("Seat");f.Until(()=>f.Game.Current==100);Check(f.Game.N("start-100")==0,"no premature engine action while seating physics unsettled");f.Stage("InitialView");Check(f.Game.N("start-100")==1&&f.Has("waiting-for-exact-pair-motion-and-contact"),"observed later completion admits one start");f.Stop();f.SafeRetired();});
        Test("transitional driver readbacks wait only for the reserved seat or exit",()=>{var f=new Fixture();f.Game.SeatDriverLag=.4;f.Game.ExitDriverLag=.5;f.Begin();f.Stage("InitialView");Check(f.Has("driver-seat-readback-pending")&&f.Game.N("seat")==1,"seat relationship observed after callback lag");f.Stop();f.SafeRetired();Check(f.Has("exit-occupancy-readback-pending")&&f.Game.N("exit")==1,"exit relationship fully observed before deletion");});
        Test("position restoration waits for later readback and never reissues",()=>{var f=new Fixture();f.Game.MoveDelay=2;f.Begin();f.Stage("InitialView");f.Run.Stop("AUTHORED restore wait",f.Capture);f.Stage("Restore");f.Step();Check(!f.Run.State.Finished,"restore request alone is not completion");int moves=f.Game.N("move");f.Finish();Check(f.Game.N("move")==moves&&f.Has("saved-view-or-position-readback-pending")&&f.Has("saved-view-readback-verified"),"one restoration and observed completion");});
        Test("B never starts; timeout retires without successful startup",()=>{var f=new Fixture();f.Game.BNeverStarts=true;f.Begin();f.Finish();Check(f.Has("TIMED_OUT BInitial")&&f.Game.N("start-101")==1&&f.Game.Profiles.Count==0,"exact B timeout and no retry");f.SafeRetired();});
        Test("near-deadline seating succeeds without renewing session",()=>{var f=new Fixture();f.Game.SeatDelay=4.8;f.Begin();f.Stage("Seat");long deadline=f.Run.State.Deadline;f.Stage("EngineA");Check(f.Run.State.Deadline==deadline&&f.Game.N("seat")==1,"4.8 second readback succeeds with immutable deadline");f.Stop();f.SafeRetired();});
        Test("late seating times out but later exit can still complete",()=>{var f=new Fixture();f.Game.SeatDelay=5.2;f.Begin();f.Finish();Check(f.Has("TIMED_OUT SeatInitial")&&f.Game.N("seat")==1&&f.Game.Profiles.Count==0,"late seat is not experimental admission");f.SafeRetired();});
        Test("never-completing seat remains unresolved rather than deleting future target",()=>{var f=new Fixture();f.Game.SeatNever=true;f.Begin();f.Finish();Check(f.Has("TIMED_OUT SeatInitial")&&f.Game.N("seat")==1&&!f.Run.State.Retired&&f.Game.DeleteWrites==0,"in-flight seating never resent or raced with deletion");});
        Test("identity loss while seating cannot be reacquired or deleted",()=>{var f=new Fixture();f.Game.SeatDelay=2;f.Begin();f.Stage("Seat");f.Step();f.Game.Entities[100].Token=999;f.Step();f.Game.Entities[100].Token=11;f.Finish();Check(!f.Run.State.Retired&&f.Game.N("delete-100")==0&&f.Game.Profiles.Count==0,"sticky lost lifetime even when old token restored");});
        Test("unknown engine return is consumed once; safe cleanup still works",()=>{var f=new Fixture();f.Game.ThrowEngine=true;f.Begin();f.Finish();Check(f.Game.N("start-100")==1&&f.Has("outcome-unknown step=AInitial")&&f.Game.Profiles.Count==0,"uncertain engine setter not resent");f.SafeRetired();});
        Test("unknown seat return with later seating waits then exits once",()=>{var f=new Fixture();f.Game.ThrowSeat=true;f.Game.SeatDelay=1.2;f.Begin();f.Finish();Check(f.Game.N("seat")==1&&f.Game.N("exit")==1,"in-flight uncertain seating observed before cleanup exit");f.SafeRetired();});
        Test("delayed deletion including lost return observes disappearance, never repeats",()=>{var f=new Fixture();f.Game.ThrowDelete=true;f.Game.DeleteDelay=2;f.Begin();f.Stage("PairSettle");f.Stop();f.SafeRetired();Check(f.Has("delete-outcome-unknown"),"unknown return retained separately from disappearance");});
        Test("deletion never disappears times out without resend",()=>{var f=new Fixture();f.Game.DeleteNever=true;f.Begin();f.Stage("PairSettle");f.Stop();Check(!f.Run.State.Retired&&f.Game.N("delete-100")==1&&f.Game.N("delete-101")==1&&f.Has("TIMED_OUT Retire"),"delete readback bounded independently");});
        Test("delayed exit survives cleanup before audio and never resends",()=>{var f=new Fixture();f.Game.ExitDelay=4;f.Begin();f.Stage("EngineA");f.Stop();Check(f.Game.N("exit")==1&&f.Game.Profiles.Count==0,"one safe exit, no audio dependency");f.SafeRetired();});
        Test("unsafe retirement ownership remains refused",()=>{var f=new Fixture();f.Begin();f.Stage("PairSettle");f.Game.Entities[101].Owned=false;f.Stop();Check(!f.Run.State.Retired&&f.Game.N("delete-101")==0,"unknown ownership never deleted");});
        Test("lost second create return cannot claim complete retirement",()=>{var f=new Fixture();f.Game.ThrowCreateB=true;f.Begin();f.Finish();Check(f.Game.Created==2&&f.Game.Profiles.Count==0&&!f.Run.State.Retired&&f.Has("creation-outcome-unknown-no-complete-owned-pair-inventory"),"unknown created entity never reacquired or reported absent");Check(f.Game.N("delete-101")==0,"no deletion by convenient unknown handle");});
        Test("cleanup tolerates dead undriveable owned empty pair",()=>{var f=new Fixture();f.Begin();f.Stage("PairSettle");f.Game.Entities[100].Dead=true;f.Game.Entities[100].Driveable=false;f.Stop();f.SafeRetired();});
        Test("blocked local location refuses rather than distant teleport",()=>{var f=new Fixture();f.Game.BlockSite=true;f.Begin();f.Finish();Check(f.Has("all-four-local-layouts-blocked")&&f.Game.Created==0&&f.Game.N("move")==0,"no location fallback or pair");});
        Test("one initial normal exit never adopts the pre-existing vehicle",()=>{var f=new Fixture();f.Game.Entities.Add(99,new SetupGame11.Entity{Handle=99,Driver=2});f.Game.Current=99;f.Begin();f.Stage("InitialView");Check(f.Game.N("exit")==1&&f.Game.N("start-99")==0&&f.Game.N("delete-99")==0,"pre-existing vehicle only receives one normal player exit");f.Stop();Check(f.Run.State.Retired&&f.Game.Entities[99].Exists,"pre-existing vehicle survives owned-pair retirement");});
        Test("ground and model readiness have separate bounded waits",()=>{var f=new Fixture();f.Game.GroundNever=true;f.Begin();f.Finish();Check(f.Has("TIMED_OUT Site")&&f.Game.Created==0,"ground unavailable never creates pair");var m=new Fixture();m.Game.ModelDelay=8;m.Begin();m.Finish();Check(m.Has("TIMED_OUT Models")&&m.Game.Created==0&&m.Run.State.Retired,"model timeout cleanup independent");});
        Test("camera interpolation waits; endless interpolation times out",()=>{var f=new Fixture();f.Game.CameraDelay=3;f.Begin();f.Stage("Stability");Check(f.Game.Profiles.Count==0,"camera settling precedes capture");f.Stop();f.SafeRetired();var n=new Fixture();n.Game.CameraDelay=20;n.Begin();n.Finish();Check(n.Has("camera-or-operating-state-did-not-settle")&&n.Game.Profiles.Count==0,"camera timeout stops");n.SafeRetired();});
        Test("conflicting occupant is immediate unsafe, no seating",()=>{var f=new Fixture();f.Begin();f.Stage("PairSettle");f.Game.Entities[101].Passenger=7;f.Step();Check(f.Has("conflicting-occupant")&&f.Game.N("seat")==0,"conflict refused immediately");f.Finish();Check(f.Game.N("delete-101")==0,"occupied B not deleted");});
        Test("B motion during mandatory stability window stops without a replacement take",()=>{var f=new Fixture();f.Begin();f.Stage("Stability");f.Game.Entities[101].Speed=.2f;f.Game.Later(.5,()=>f.Game.Entities[101].Speed=0);f.Step();f.Finish();Check(f.Has("B stability lost")&&f.Game.N("start-101")==1&&f.Game.Profiles.Count==0,"no B maintenance or retake");f.SafeRetired();});
        Test("stock-positive ambiguity prevents private comparison",()=>{var f=new Fixture();f.Begin();f.At("B-pre");f.Review();f.At("baseline");f.Review();f.At("0");f.Review();f.At("1");f.Review("Ambiguous");f.Finish(true);Check(f.Game.Profiles.SequenceEqual(new[]{"BATI","ADDER","BATI"}),"only permitted terminal release after ambiguous ADDER");f.SafeRetired();});
        Test("stop at each setup transition uses independent reverse path",()=>{foreach(string stage in new[]{"BeginDurable","PrepareSite","Spawn","PairSettle","Seat","EngineA","EngineB","InitialView","StabilitySettle","Stability","LeaveBPre","AOffBPre","BViewPre","BCameraPre","BPreSettle","BWindow","SeatBaseline","EngineBaseline","BaselineView","ASettle","Horn","BaselineIdle"}){
            var f=new Fixture();f.Begin();for(int i=0;i<12000&&f.Run.State.Stage!=stage&&!f.Run.State.Finished;i++){if(f.Run.State.AwaitingReview)f.Review();f.Step();}Check(f.Run.State.Stage==stage,"reach stop stage "+stage);f.Stop();Check(f.Game.Profiles.Count==0&&f.Run.State.Retired,"cleanup before audio at "+stage);Check(f.Game.N("delete-100")<=1&&f.Game.N("delete-101")<=1,"no duplicate delete "+stage);
        }});
        Test("stop while issued seat, exit and local placement are pending",()=>{foreach(string stage in new[]{"Seat","LeaveBPre","BViewPre"}){var f=new Fixture();f.Begin();f.Stage(stage);f.Step();int seat=f.Game.N("seat"),exit=f.Game.N("exit");f.Stop();f.SafeRetired();Check(f.Game.N("seat")==seat&&f.Game.N("exit")<=exit+1,"pending command never reissued "+stage);}});
        Test("session expiry never renews deadline",()=>{var f=new Fixture();f.Begin();f.Stage("Seat");long deadline=f.Run.State.Deadline;f.Step(601);Check(f.Run.State.Finished&&f.Run.State.Deadline==deadline&&f.Game.Profiles.Count==0,"absolute expiry prevents new work");});
        Console.WriteLine("PASS cases="+cases+" assertions="+assertions+"; AUTHORED delayed responses through actual runner, native adapter and SDK InputArgument; zero GTA launches, no live sound proof");return 0;
    }catch(Exception e){if(current!=null){System.IO.File.WriteAllLines(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"failure-journal.txt"),current.Log.Lines);Console.Error.WriteLine("Actual stage="+current.Run.State.Stage+" profiles="+string.Join(",",current.Game.Profiles));}Console.Error.WriteLine(e);return 1;}}
}
